 static int RearValidateProject(object value){
  int count=0;var seen=new HashSet<string>();Action<object> visit=null;visit=o=>{var d=o as Dictionary<string,object>;if(d!=null){object kind,r,c;if(d.TryGetValue("Kind",out kind)&&object.Equals(kind,"body")&&d.TryGetValue("Reference",out r)&&d.TryGetValue("ComponentReference",out c)&&seen.Add((string)c+"|"+(string)r)){if(!(Resolve(model,(string)r) is Body2)||!(Resolve(model,(string)c) is Component2))throw new Exception("Merged body reference does not resolve");count++;}foreach(var child in d.Values)visit(child);}else{var a=o as object[];if(a!=null)foreach(var child in a)visit(child);}};visit(value);return count;
